function engineerBanner(e={}){const mode=e.mode||'HOLD',q=(e.queue||[]).map(x=>`${esc(x.title)} · ${esc(x.detail)}`).join('  ◆  '),raw=e.title||'COLLECTING TELEMETRY',title=raw.toUpperCase().startsWith(mode.replace('_',' '))?raw:`${mode.replace('_',' ')} — ${raw}`;const icons={ATTACK:'ϟ',DEFEND:'◇',PIT:'P',RED_FLAG:'⚑',HOLD:'—'};return`<div class="engineer-banner ${esc(mode)}"><div class="engineer-main"><div class="engineer-icon">${icons[mode]||'—'}</div><div><div class="engineer-title">${esc(title)}</div><div class="engineer-detail">${esc(e.detail||'Waiting for a stable live context')}</div></div></div><div class="engineer-next"><b>NEXT</b> &nbsp; ${q||'Monitor tyre state, traffic and race control'}</div></div>`}
