let _trackPathCache={key:'',path:''};
function trackSvg(points=[],progress=0){if(!points.length)return'<div class="muted">MAP UNAVAILABLE</div>';const key=points.length+':'+points[0]+':'+points[points.length-1];if(_trackPathCache.key!==key)_trackPathCache={key,path:points.map(p=>p.join(',')).join(' ')};const path=_trackPathCache.path,idx=Math.min(points.length-1,Math.floor(progress*points.length)),p=points[idx]||points[0];return`<svg class="track-svg" viewBox="0 0 280 145"><polyline points="${path}"/><circle cx="${p[0]}" cy="${p[1]}" r="4"/></svg>`}
function paceSvg(rows=[]){if(rows.length<2)return'<div class="empty">COLLECTING VALID LAPS</div>';const w=850,h=145,p=18,vals=rows.map(x=>x.time_ms),lo=Math.min(...vals),hi=Math.max(...vals),span=Math.max(500,hi-lo),pts=rows.map((r,i)=>[p+i*(w-2*p)/(rows.length-1),p+(r.time_ms-lo)*(h-2*p)/span]);const line=pts.map(x=>x.join(',')).join(' '),area=`${p},${h-p} ${line} ${w-p},${h-p}`;return`<svg class="pace-svg" viewBox="0 0 ${w} ${h}"><defs><linearGradient id="paceArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b82f6" stop-opacity=".28"/><stop offset="1" stop-color="#3b82f6" stop-opacity="0"/></linearGradient></defs>${[.15,.5,.85].map(y=>`<line class="gridline" x1="${p}" x2="${w-p}" y1="${p+y*(h-2*p)}" y2="${p+y*(h-2*p)}"/>`).join('')}<polygon class="area" points="${area}"/><polyline class="line" points="${line}"/>${pts.map((x,i)=>`<circle class="point" cx="${x[0]}" cy="${x[1]}" r="${vals[i]===lo?5:3}" style="fill:${vals[i]===lo?'#34d399':''}"/><text x="${x[0]}" y="${h-3}" text-anchor="middle">${rows[i].lap}</text>`).join('')}</svg>`}

