function profileView(){const root=state.profile||{},stages=root.stages||{},feedback=root.feedback||{},names=[['time_trial','TIME TRIAL','Your raw-pace laboratory: PB trace, sectors, validity and repeatability. Race fuel and wear are excluded.'],['practice','PRACTICE','Validate setup, long-run tyre behaviour and fuel use.'],['qualifying','QUALIFYING','Maximise tyre preparation and one-lap execution.'],['race','RACE','Protect tyres, fuel and ERS without losing pace.']];return`<div class="view"><div class="view-head"><div><span class="eyebrow">CONTINUOUS PERSONAL CALIBRATION</span><h1>Driver Profile</h1><p>${root.sessions||0} sessions · ${root.laps||0} recorded laps. Time Trial, Practice, Qualifying and Race are learned separately.</p></div><div class="field"><label>FILTER CIRCUIT</label><select id="profile-track"><option value="">All tracks</option>${(state.boot?.tracks||[]).map(t=>`<option ${root.track===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div></div><div class="grid grid-2">${names.map(([key,title,sub])=>{const p=stages[key]||{};return`<article class="card phase-card"><div class="card-head"><strong>${title}</strong><span class="right confidence ${String(p.confidence||'LOW').toLowerCase()}">${esc(p.confidence||'LOW')}</span></div><p class="muted">${sub}</p><div class="metric">${p.clean_laps||0}<small> clean laps</small></div><div class="data-rows"><span>Best / median</span><b>${fmtMs(p.best_lap_ms)} / ${fmtMs(p.median_lap_ms)}</b><span>Consistency</span><b>±${n((p.pace_consistency_ms||0)/1000,2)}s</b>${key==='time_trial'?'':`<span>Fuel per lap</span><b>${n(p.fuel_per_lap,2)} kg</b><span>Wear per lap</span><b>${n(p.wear_per_lap,2)}%</b><span>ERS net use</span><b>${n((p.ers_net_use_j||0)/1000,0)} kJ</b>`}<span>Invalid rate</span><b>${n(p.invalid_rate,0)}%</b></div><div class="feedback-list">${(feedback[key]||[]).map(x=>`<div><b>${esc(x.title)}</b><p>${esc(x.detail)}</p></div>`).join('')}</div></article>`}).join('')}</div></div>`}
function reportsView(){const sessions=state.boot?.sessions||[];return`<div class="view"><div class="view-head"><div><span class="eyebrow">BEAUTIFUL, EXPLAINABLE, IN APP</span><h1>Race Reports</h1><p>Open a session as an engineering story: pace, stints, strategy changes, race control and learned improvements.</p></div><button class="button" id="open-report-folder">LEGACY EXPORT FOLDER</button></div><div class="grid grid-3 report-library">${sessions.map(r=>`<article class="card"><span class="label">${esc(r.display_name)}</span><h3>${esc(r.track_name||'Unknown track')}</h3><p class="muted">${esc(r.session_label||r.session_type)} · ${r.completed_laps||0} laps · best ${fmtMs(r.best_lap_ms)}</p><button class="button primary session-report" data-session-report="${r.id}">OPEN IN-APP REPORT</button></article>`).join('')}</div><article class="card" style="margin-top:12px"><div class="card-head"><strong>Existing CSV / HTML exports</strong><span class="right muted">kept fully compatible</span></div><div class="table-wrap"><table class="table"><tbody>${state.reports.map(r=>`<tr><td>${esc(r.name)}</td><td>${new Date(r.modified*1000).toLocaleString()}</td><td><button class="button open-report" data-path="${esc(r.path)}">OPEN</button></td></tr>`).join('')}</tbody></table></div></article></div>`}
