function liveEnhancedView(){const e=state.live?.ers||{},base=liveView();return base.replace('<span>TRACK',`<span>ERS CALL <b class="${e.action==='DEPLOY'?'good':e.action==='RECHARGE'?'sky':'warn'}">${esc(e.action||'LEARNING')}</b></span><span>TRACK`)}
function paceSpark(rows=[]){if(!rows||rows.length<2)return'<div class="pace-spark-empty">COLLECTING VALID LAPS</div>';const w=520,h=48,pad=5,vals=rows.map(r=>r.time_ms),lo=Math.min(...vals),hi=Math.max(...vals),span=Math.max(400,hi-lo),pts=rows.map((r,i)=>[pad+i*(w-2*pad)/(rows.length-1),pad+(r.time_ms-lo)*(h-2*pad)/span]),line=pts.map(pt=>pt.join(',')).join(' '),area=`${pad},${h-pad} ${line} ${w-pad},${h-pad}`,last=pts[pts.length-1],lp=pts[vals.indexOf(lo)];return`<svg class="pace-spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="cpArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b82f6" stop-opacity=".28"/><stop offset="1" stop-color="#3b82f6" stop-opacity="0"/></linearGradient></defs><polygon points="${area}" fill="url(#cpArea)"/><polyline points="${line}" fill="none" stroke="#3b82f6" stroke-width="2" vector-effect="non-scaling-stroke"/><circle cx="${lp[0]}" cy="${lp[1]}" r="3.5" fill="#34d399"/><circle cx="${last[0]}" cy="${last[1]}" r="3" fill="#edf1f7"/></svg>`}
function couchView(){const {x,p,l,d,s,st,displayEngineer,coach,field,ahead,behind,pace}=liveModel();const mode=displayEngineer?.mode||'HOLD',engMap={ATTACK:'green',DEFEND:'red',RED_FLAG:'red',PIT:'amber',HOLD:'slate'},eng=engMap[mode]||'slate',icons={ATTACK:'ϟ',DEFEND:'◇',PIT:'P',RED_FLAG:'⚑',HOLD:'—'},dv=d.seconds,peri=dv==null?'slate':dv<-.02?'green':dv>.02?'red':'slate',dn=dv==null?'--':`${dv<0?'−':'+'}${n(Math.abs(dv),2)}`,dCls=dv==null?'':dv<0?'good':dv>0?'bad':'',word=dv==null?'LEARNING':dv<-.02?'GAINING':dv>.02?'LOSING':'ON REFERENCE';const tyres=x.tyres||[];let worst=tyres[0]||{corner:'--',wear:0,temp:0};tyres.forEach(t=>{if((t.wear||0)>(worst.wear||0))worst=t});const hot=tyres.reduce((a,t)=>Math.max(a,t.temp||0),0),tyreCrit=(worst.wear||0)>=70||hot>=115;const action=st.action||'STAY OUT',isPit=/PIT/i.test(action),pitNow=action==='PIT NOW',pitV=`${action}${st.window_start?` · L${st.window_start}–${st.window_end}`:''}`,pitSub=st.predicted_rejoin?`Rejoin P${st.predicted_rejoin}${st.compound?` · fit ${esc(st.compound)}`:''}`:(st.detail||st.headline||'Managing the current stint');const ga=ahead?Math.abs(ahead.gap_to_player):null,gb=behind?Math.abs(behind.gap_to_player):null,aheadHot=ga!=null&&ga<=1.0,behindHot=gb!=null&&gb<=1.0;const vsAvg=Number(pace.last_vs_average_ms||0),trend=pace.trend||'LEARNING',trendCls=trend==='IMPROVING'?'good':trend==='FADING'?'bad':'sky',phase=x.race_control?.phase||'GREEN',flagCls=phase==='GREEN'?'good':phase==='RED_FLAG'?'bad':'warn';return`<div class="view couch-dashboard" data-peri="${peri}" data-glow="${eng}"><button class="live-fullscreen" id="live-fullscreen" title="Exit couch mode (F11)">▣ EXIT COUCH MODE <small>F11</small></button><div class="couch-edge"></div><div class="peri"></div>
  <div class="couch-body"><div class="couch-left"><div class="bigeng ${eng}"><div class="ic">${icons[mode]||'—'}</div><div><div class="t">${esc(displayEngineer?.title||'COLLECTING TELEMETRY')}</div><div class="d">${esc(displayEngineer?.detail||'Waiting for a stable live context')}</div></div></div><div class="deltawrap"><div class="dn ${dCls}">${dn}</div><div class="word ${dCls}">${word}</div><div class="ref">SECONDS VS YOUR REFERENCE LAP</div></div><div class="microbig">${(x.micro_sectors||[]).map(m=>`<i class="${m.delta==null?'':m.delta<-.03?'gain':m.delta>.03?'loss':''}"></i>`).join('')}</div></div>
  <div class="couch-rail"><div class="ctile pit ${isPit?'amber':''} ${pitNow?'now':''}"><div class="cap">PIT CALL</div><div class="v">${esc(pitV)}</div><div class="sub">${esc(pitSub)}</div></div><div class="ctile tyre ${tyreCrit?'crit':''}"><div class="cap">WORST TYRE</div><div class="v">${esc(worst.corner)} ${n(worst.wear)}% · ${n(worst.temp)}°C</div></div><div class="cgaps"><div class="cgap ahead ${aheadHot?'hot':''}"><div class="who"><span class="arw">▲ AHEAD</span><span class="nm">${esc(ahead?.name||'LEADER')}</span></div><div class="gv">${ga!=null?n(ga,1)+'s':'--'}</div></div><div class="cgap behind ${behindHot?'hot':''}"><div class="who"><span class="arw">▼ BEHIND</span><span class="nm">${esc(behind?.name||'LAST')}</span></div><div class="gv">${gb!=null?n(gb,1)+'s':'--'}</div></div></div><div class="ctwo"><div class="cmini"><div class="cap">ERS</div><div class="v sky">${p.ers_pct||0}%</div></div><div class="cmini"><div class="cap">FUEL Δ</div><div class="v ${Number(p.fuel_delta_laps||0)>=0?'good':'bad'}">${p.fuel_delta_laps>=0?'+':''}${n(p.fuel_delta_laps,1)}L</div></div></div></div></div>
  <div class="couch-pace"><div class="cp-head"><strong>⌁ RACE PACE</strong><div class="cp-kpis"><span>AVG <b>${fmtMs(pace.average_ms)}</b></span><span>LAST <b>${fmtMs(pace.last_ms||l.last_ms)}</b></span><span>VS AVG <b class="${vsAvg<=0?'good':'bad'}">${vsAvg>=0?'+':''}${n(vsAvg/1000,2)}s</b></span><span>TREND <b class="${trendCls}">${esc(trend)}</b></span></div></div><div class="cp-spark">${paceSpark(x.pace||[])}</div></div>
  <div class="couch-foot"><div class="cell"><span class="k">POSITION</span><span class="v">P${p.position||'--'} / ${field.length||'--'}</span></div><div class="cell"><span class="k">LAP</span><span class="v">${p.lap_num||'--'} / ${s.laps||'--'}</span></div><div class="cell"><span class="k">TYRE</span><span class="v warn">${esc(p.compound||'--')} · ${p.tyre_age??'--'}L</span></div><div class="cell"><span class="k">LAST LAP</span><span class="v">${fmtMs(l.last_ms)}</span></div><div class="cell"><span class="k">FLAG</span><span class="v ${flagCls}">${esc(phase)}</span></div></div></div>`}
function preRaceEnhancedView(){return preRaceView()}
function setupClipboardText(){const setup=state.preRace?.setup,variants=setup?.brendon_package?.variants||{},mode=state.preSetupMode in variants?state.preSetupMode:'race',s=variants[mode];if(!s)return'';const bias=(s.brake_bias||[]).join('–');return`${setup.track} · Brendon Leigh v1.5 · ${mode.toUpperCase()}\nWings (front/rear): ${s.front_wing} / ${s.rear_wing}\nDifferential (on/off): ${s.on_throttle_diff}% / ${s.off_throttle_diff}%\nCamber/toe: ${s.camber_toe}\nSuspension (front/rear): ${s.front_suspension} / ${s.rear_suspension}\nAnti-roll bars (front/rear): ${s.front_anti_roll_bar} / ${s.rear_anti_roll_bar}\nRide height (front/rear): ${s.front_ride_height} / ${s.rear_ride_height}\nBrakes (pressure/bias): ${s.brake_pressure}% / ${bias}\nTyres PSI (FL/FR/RL/RR): ${s.front_left_pressure} / ${s.front_right_pressure} / ${s.rear_left_pressure} / ${s.rear_right_pressure}`}
