function scheduleTick(){tick().finally(()=>setTimeout(scheduleTick,100))}
let initialized=false;
async function init(){if(initialized)return;initialized=true;state.route=location.hash.slice(1)||'solo';state.live=await api().get_live_snapshot();nav();render();logClient('frontend_ready',{route:state.route,user_agent:navigator.userAgent});if(!sessionStorage.getItem('welcomeDismissed'))showWelcome(false);$('#welcome-dismiss')?.addEventListener('click',hideWelcome);scheduleTick();api().get_bootstrap().then(boot=>{state.boot=boot;nav();if(!['solo','split','strategy'].includes(state.route))render();else topbar(true)}).catch(error=>logClient('bootstrap_error',{message:String(error?.message||error)},10000));window.addEventListener('keydown',e=>{if(e.key==='F11'){e.preventDefault();state.route==='solo'?toggleLiveFullscreen():api().toggle_fullscreen()}if(e.key==='Escape'){if($('#welcome')&&!$('#welcome').classList.contains('welcome-hidden')){hideWelcome();return}if(state.liveFocus){e.preventDefault();toggleLiveFullscreen()}}})}
nav();render();
window.addEventListener('error',e=>logClient('javascript_error',{message:e.message,source:e.filename,line:e.lineno,column:e.colno},2000));
window.addEventListener('unhandledrejection',e=>logClient('unhandled_rejection',{message:String(e.reason?.message||e.reason||'unknown')},2000));
window.addEventListener('pywebviewready',init);if(api())init();
async function runScenarioSelfTest(){const base=structuredClone(state.live||{}),failures=[],scenarios=[
  ['green',{race_control:{phase:'GREEN'}}],['safety-car',{race_control:{phase:'SC'}}],['virtual-safety-car',{race_control:{phase:'VSC'}}],
  ['red-flag',{race_control:{phase:'RED_FLAG'},engineer:{mode:'RED_FLAG',title:'RED FLAG — SESSION SUSPENDED',detail:'Strategy frozen',queue:[]},strategy:{action:'REASSESS',headline:'RED FLAG — STRATEGY FROZEN'}}],
  ['formation',{race_control:{phase:'FORMATION'},engineer:{mode:'HOLD',title:'FORMATION LAP — STRATEGY CALIBRATING',detail:'Reading fresh car state',queue:[]},strategy:{action:'REASSESS',headline:'FORMATION LAP — STRATEGY CALIBRATING'}}],
  ['restarting',{race_control:{phase:'RESTARTING'},engineer:{mode:'HOLD',title:'RESTART — READING FRESH CAR STATE',detail:'Reading fresh compound and fuel',queue:[]},strategy:{action:'REASSESS',headline:'RESTART — READING FRESH CAR STATE'}}],
  ['race-finish',{race_control:{phase:'GREEN',finished:true},engineer:{mode:'HOLD',title:'CHEQUERED FLAG — SESSION COMPLETE',detail:'Report preparation',queue:[]},strategy:{action:'REASSESS',headline:'CHEQUERED FLAG — SESSION COMPLETE'}}],
  ['pit-now',{strategy:{action:'PIT NOW',headline:'BOX THIS LAP — FIT HARD',window_start:14,window_end:14,predicted_rejoin:12,evidence:['Critical wear']},engineer:{mode:'PIT',title:'BOX THIS LAP — FIT HARD',detail:'Commit now',queue:[]}}],
  ['rain-crossover',{session:{weather_name:'Heavy rain',weather:4},strategy:{action:'PIT NOW',headline:'BOX — INTERMEDIATE',compound:'Intermediate',evidence:['Weather crossover']}}],
  ['critical-damage',{engineer:{mode:'PIT',title:'BOX — FRONT WING DAMAGE',detail:'Front wing 48%',queue:[]}}],
  ['critical-wear',{player:{tyre_wear:[78,77,73,75]},strategy:{action:'PIT NOW',headline:'BOX — CRITICAL TYRE WEAR',evidence:['Worst tyre 78%']}}],
  ['fuel-deficit',{player:{fuel_kg:11.2,fuel_delta_laps:-1.1},engineer:{mode:'HOLD',title:'FUEL TARGET — LIFT AND COAST',detail:'Recover 1.1 laps',queue:[]}}],
  ['tyre-overheat',{player:{tyre_temps:[111,109,113,108]},engineer:{mode:'HOLD',title:'TYRES HOT — PROTECT EXITS',detail:'Rear surface temperature high',queue:[]}}],
  ['low-battery',{ers:{action:'RECHARGE',title:'ERS: RECOVERY LAP'},player:{ers_pct:8,ers_mode:'Boost'}}],
  ['attack-ers',{ers:{action:'DEPLOY',title:'ERS: BOOST NOW'},player:{ers_pct:71,ers_mode:'Boost'}}],
  ['time-trial',{session:{type:'Time Trial',laps:0},strategy:{action:'REASSESS',headline:'RACE STRATEGY STANDBY'}}],
  ['qualifying',{session:{type:'Q3'},ers:{action:'DEPLOY',title:'ERS: BOOST ON EXIT'}}],
  ['practice',{session:{type:'Practice 2'},strategy:{action:'REASSESS',headline:'RACE STRATEGY STANDBY'}}],
  ['pit-lane',{player:{pit_status:1,speed_kmh:79,gear:3},engineer:{mode:'HOLD',title:'PIT LANE — LIMITER',detail:'Service in progress',queue:[]}}],
  ['penalty',{lap:{penalties:5,warnings:3,cuts:2},engineer:{mode:'HOLD',title:'PENALTY — FIVE SECONDS',detail:'Account for stop loss',queue:[]}}],
  ['partial-packet',{lap:{},player:{},field:[],tyres:[],pace:[],micro_sectors:[]}],
  ['disconnected',{connection:{live:false,packets:0},session:{},player:{},lap:{},field:[],tyres:[],pace:[],micro_sectors:[],strategy:{},ers:{}}],
  ['large-field',{field:Array.from({length:24},(_,i)=>({position:i+1,name:`DRIVER ${i+1}`,gap_to_player:i-10}))}],
  ['message-pressure',{engineer:{mode:'ATTACK',title:'ATTACK WINDOW',detail:'Live context',queue:Array.from({length:12},(_,i)=>({title:`CALL ${i+1}`,detail:'Detailed evidence'}))}}]
];state.route='solo';render();const root=$('#content').firstElementChild;for(let cycle=0;cycle<20;cycle++)for(const [name,change] of scenarios){try{state.live={...structuredClone(base),...structuredClone(change),session:{...(base.session||{}),...(change.session||{})},player:{...(base.player||{}),...(change.player||{})},lap:{...(base.lap||{}),...(change.lap||{})}};render(true);const visible=$('#content').textContent;if($('#content').firstElementChild!==root)failures.push(`${name}: live root replaced`);if(visible.includes('undefined'))failures.push(`${name}: undefined rendered`);if(['red-flag','formation','restarting','race-finish'].includes(name)&&state.live.strategy?.action!=='REASSESS')failures.push(`${name}: tactical strategy not suppressed`);if(name==='red-flag'&&!visible.includes('RED FLAG'))failures.push('red-flag: alert missing')}catch(error){failures.push(`${name}: ${error.message}`)}}for(const route of ['split','strategy','prerace','home']){try{state.route=route;render();if(!$('#content').firstElementChild)failures.push(`${route}: empty route`)}catch(error){failures.push(`${route}: ${error.message}`)}}const result={status:failures.length?'FAIL':'PASS',scenarios:scenarios.length,cycles:20,stablePatches:state.debug.patches,fullRenders:state.debug.fullRenders,failures};document.body.innerHTML=`<pre id="selftest-result" data-status="${result.status}">${esc(JSON.stringify(result,null,2))}</pre>`}
if(location.search.includes('debug'))window.__f1Debug={state,nav,render};
if(location.search.includes('selftest'))setTimeout(runScenarioSelfTest,50);
if(location.search.includes('demo')&&!window.pywebview)setTimeout(()=>showWelcome(false),50);
